import 'package:file_picker/file_picker.dart';
import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import 'package:share_plus/share_plus.dart';
import '../state/app_state.dart';
import '../services/storage_service.dart';
import '../widgets/app_ui.dart';

class MoreScreen extends StatelessWidget {
  const MoreScreen({super.key});
  @override
  Widget build(BuildContext context) {
    final s = context.watch<AppState>();
    return ListView(padding: const EdgeInsets.fromLTRB(20, 22, 20, 90), children: [const Text('Workspace', style: TextStyle(fontSize: 10, letterSpacing: 1.4, color: gold, fontWeight: FontWeight.w900)), const SizedBox(height: 5), const Text('More', style: TextStyle(fontSize: 29, fontWeight: FontWeight.w900, color: ink)), const SizedBox(height: 20), SurfaceCard(child: Row(children: [const BrandMark(size: 52), const SizedBox(width: 14), Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(s.practitionerName, style: const TextStyle(fontSize: 17, fontWeight: FontWeight.w900, color: ink)), const SizedBox(height: 4), Text(s.firmName, style: const TextStyle(color: muted, fontSize: 12))])), IconButton(onPressed: () => _profile(context,s), icon: const Icon(Icons.edit_rounded))])), const SizedBox(height: 18), _tile(context, Icons.notifications_active_outlined, 'Reminders', 'Day-before hearings and hearing-day updates', trailing: Switch(value: s.notificationsEnabled, onChanged: (v) => s.setNotifications(v))), _tile(context, Icons.ios_share_rounded, 'Backup data', 'Export your cases and schedule to a private JSON file', onTap: () => _backup(context)), _tile(context, Icons.restore_rounded, 'Restore data', 'Restore a CaseCraft JSON backup on this device', onTap: () => _restore(context)), _tile(context, Icons.shield_outlined, 'Privacy model', 'CaseCraft stores practice data locally on the device. No account is required.', onTap: () => _privacy(context)), const SizedBox(height: 14), const Text('About', style: TextStyle(fontSize: 13, color: muted, fontWeight: FontWeight.w800)), const SizedBox(height: 7), const Text('CaseCraft 1.0.0', style: TextStyle(color: ink, fontWeight: FontWeight.w900)), const SizedBox(height: 5), const Text('A legal command centre designed for focused daily practice management.', style: TextStyle(color: muted, height: 1.4))]);
  }

  Widget _tile(BuildContext context, IconData icon, String title, String sub, {VoidCallback? onTap, Widget? trailing}) => Padding(padding: const EdgeInsets.only(bottom: 10), child: SurfaceCard(padding: EdgeInsets.zero, onTap: onTap, child: ListTile(contentPadding: const EdgeInsets.symmetric(horizontal: 17, vertical: 5), leading: Container(width: 42, height: 42, decoration: BoxDecoration(color: gold.withValues(alpha: .11), borderRadius: BorderRadius.circular(14)), child: Icon(icon, color: gold, size: 21)), title: Text(title, style: const TextStyle(fontWeight: FontWeight.w900, color: ink)), subtitle: Padding(padding: const EdgeInsets.only(top: 4), child: Text(sub, style: const TextStyle(fontSize: 11.5, color: muted))), trailing: trailing ?? const Icon(Icons.chevron_right_rounded, color: muted))));

  Future<void> _profile(BuildContext context, AppState s) async { final name=TextEditingController(text:s.practitionerName),firm=TextEditingController(text:s.firmName); await showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('Your practice'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:name,decoration:fieldDecoration('Practitioner name')),const SizedBox(height:10),TextField(controller:firm,decoration:fieldDecoration('Firm / chamber name'))]),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Cancel')),FilledButton(onPressed:()async{await s.saveProfile(name.text,firm.text);if(context.mounted)Navigator.pop(context);},child:const Text('Save'))]));name.dispose();firm.dispose(); }
  Future<void> _backup(BuildContext context) async { final file=await context.read<StorageService>().createBackupFile(); await SharePlus.instance.share(ShareParams(files:[XFile(file.path)], subject:'CaseCraft Backup')); }
  Future<void> _restore(BuildContext context) async { final picked=await FilePicker.pickFile(type:FileType.custom,allowedExtensions:['json']);final path=picked?.path;if(path==null||!context.mounted)return;final count=await context.read<AppState>().restoreBackup(path);if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Restored $count records.'))); }
  void _privacy(BuildContext context)=>showDialog(context:context,builder:(_)=>const AlertDialog(title:Text('Privacy-first by design'),content:Text('Your case records, schedule, reminders and profile are saved locally in the app. Backups only leave the device when you explicitly choose Backup data and share the generated file.')));
}
